const API='/api';
function getToken(){return localStorage.getItem('exalyte_token')}
function getUser(){return JSON.parse(localStorage.getItem('exalyte_user')||'null')}
function logout(){localStorage.clear();window.location.href='/'}
// Student Mode: lets an admin browse the live student experience (dashboard, exams,
// history, results) using their own admin account. Admin accounts already bypass every
// premium/closed/scheduled restriction server-side, so this is purely a navigation flag —
// it just stops the student pages from bouncing an admin back here, and shows a bar with
// a one-tap way back. Nothing about the admin's actual permissions changes.
function enterStudentMode(){localStorage.setItem('exalyte_student_mode','1');window.location.href='dashboard.html'}
function esc(s){return(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
function formatDate(iso){return iso?new Date(iso).toLocaleDateString():'—'}
function isImageURL(s){if(!s)return false;const t=s.trim();return t.startsWith('http')&&(t.includes('.jpg')||t.includes('.jpeg')||t.includes('.png')||t.includes('.webp')||t.includes('.gif')||t.includes('ibb.co')||t.includes('images.unsplash.com')||t.includes('i.imgur.com'))}
function formatTimeTaken(s){if(!s||s<=0)return'N/A';const m=Math.floor(s/60),sec=Math.floor(s%60);return m>0?m+'m '+sec+'s':sec+'s'}
async function apiFetch(path,opts={}){const t=getToken();const h={'Content-Type':'application/json',...(t?{Authorization:'Bearer '+t}:{})};try{const r=await fetch(API+path,{...opts,headers:h});return{ok:r.ok,status:r.status,data:await r.json().catch(()=>({}))}}catch(networkErr){return{ok:false,status:0,data:{error:'Network error: '+(networkErr.message||networkErr)}}}}
function toast(m){const t=document.getElementById('toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000)}

let allExams=[],allBatches=[],allUsers=[],editingExamId=null,editingBatchId=null,grantUserId=null;
let currentResourceType='exam',currentResourceTargetId=null;
let requiredSections=[],compulsorySections=[],normalSections=[];
const PAGE_SIZE=15;
let usersPageNum=1,examsPageNum=1,batchesPageNum=1,resultsPageNum=1,notifPageNum=1;
function paginateList(list,page,perPage){const totalPages=Math.max(1,Math.ceil(list.length/perPage));const p=Math.min(Math.max(1,page),totalPages);return{items:list.slice((p-1)*perPage,p*perPage),page:p,totalPages,total:list.length}}
function pagerHtml(page,totalPages,total,fn){if(totalPages<=1)return'';let start=Math.max(1,page-2),end=Math.min(totalPages,start+4);start=Math.max(1,end-4);let pages=[];for(let i=start;i<=end;i++)pages.push(i);let html='<div class="pager">';html+=`<button class="pager-btn" ${page<=1?'disabled':''} onclick="${fn}(${page-1})">Prev</button>`;if(start>1){html+=`<button class="pager-btn" onclick="${fn}(1)">1</button>`;if(start>2)html+='<span class="pager-ellipsis">\u2026</span>'}pages.forEach(i=>{html+=`<button class="pager-btn${i===page?' active':''}" onclick="${fn}(${i})">${i}</button>`});if(end<totalPages){if(end<totalPages-1)html+='<span class="pager-ellipsis">\u2026</span>';html+=`<button class="pager-btn" onclick="${fn}(${totalPages})">${totalPages}</button>`}html+=`<button class="pager-btn" ${page>=totalPages?'disabled':''} onclick="${fn}(${page+1})">Next</button>`;html+='</div>';html+=`<div class="pager-info">Page ${page} of ${totalPages} \u00b7 ${total} total</div>`;return html}

function levenshtein(a,b){const m=a.length,n=b.length;if(m===0)return n;if(n===0)return m;const dp=new Array(n+1);for(let j=0;j<=n;j++)dp[j]=j;for(let i=1;i<=m;i++){let prev=dp[0];dp[0]=i;for(let j=1;j<=n;j++){const tmp=dp[j];dp[j]=a[i-1]===b[j-1]?prev:1+Math.min(prev,dp[j],dp[j-1]);prev=tmp}}return dp[n]}
function normalizeSearch(s){return(s||'').toLowerCase().trim().replace(/\s+/g,' ')}
function fieldMatchScore(query,field){if(!field)return -1;const q=normalizeSearch(query),f=normalizeSearch(field);if(!q)return -1;if(f.startsWith(q))return 100;if(f.includes(q))return 90-Math.min(20,f.length-q.length);let best=Infinity;const qLen=q.length;for(let i=0;i<=Math.max(0,f.length-1);i++){const win=f.substr(i,qLen);if(!win)continue;const d=levenshtein(q,win);if(d<best)best=d}best=Math.min(best,levenshtein(q,f));const threshold=qLen<=3?1:Math.ceil(qLen*0.34);if(best<=threshold)return 60-best*8;return -1}
function fuzzyUserSearch(query){const q=normalizeSearch(query);if(!q)return[];return allUsers.map(u=>{const ns=fieldMatchScore(q,u.name);const es=fieldMatchScore(q,u.email);return{...u,_score:Math.max(ns,es)}}).filter(u=>u._score>=0).sort((a,b)=>b._score-a._score).slice(0,15)}

/* ============================================================
   FIXED: searchable-select widget
   Root cause of "select once, then stuck until refresh" AND
   "new exam doesn't appear in list without refresh":
   updateSearchableSelectUI() used to look up the trigger's
   label span via `.querySelector('.placeholder')`, but the very
   same function REMOVES the 'placeholder' class from that span
   once something is selected. So the 2nd call onwards couldn't
   find the span, `trig` was null, and `trig.textContent = ...`
   threw — silently killing whatever function called it
   (including loadExams(), which calls rebuildSearchableSelects()
   BEFORE renderExams(), so the table never re-rendered either).
   Fix: give the span a permanent lookup class `.ss-label`,
   independent of the `.placeholder` style/state class.
   Also: preserve the current selection across rebuilds (e.g.
   after creating/editing an exam) instead of silently resetting
   it to blank every time loadExams()/loadBatches() runs.
   ============================================================ */
const searchableSelects={};
function registerSearchableSelect(wrapId,items,targetInputId,onChange,options={}){
  const prev=searchableSelects[wrapId];
  const preserved=prev?prev.selectedValue:'';
  const defaultValue=options.defaultValue!==undefined?options.defaultValue:preserved;
  searchableSelects[wrapId]={items,selectedValue:defaultValue||'',targetInputId,onChange:onChange||(()=>{}),placeholder:options.placeholder||'Select...'}
}
function updateSearchableSelectUI(wrapId,q){
  const ss=searchableSelects[wrapId];
  if(!ss)return;
  const wrapEl=document.getElementById(wrapId);
  if(!wrapEl)return;
  const list=wrapEl.querySelector('.searchable-select-list');
  const trig=wrapEl.querySelector('.ss-label');
  if(!list||!trig)return;
  let filtered=ss.items;
  if(q){filtered=ss.items.map(i=>({...i,_s:Math.max(fieldMatchScore(q,i.label),fieldMatchScore(q,i.desc||''))})).filter(i=>i._s>=0).sort((a,b)=>b._s-a._s)}
  if(ss.selectedValue){
    const sel=ss.items.find(i=>String(i.value)===String(ss.selectedValue));
    if(sel){trig.textContent=sel.label;trig.classList.remove('placeholder')}
    else{trig.textContent=ss.placeholder;trig.classList.add('placeholder')}
  }else{
    trig.textContent=ss.placeholder;
    trig.classList.add('placeholder')
  }
  list.innerHTML=filtered.length?filtered.map(i=>`<div class="searchable-select-option${String(i.value)===String(ss.selectedValue)?' selected':''}" onclick="selectSearchableOption('${wrapId}','${i.value}')"><span>${esc(i.label)}</span>${i.desc?`<span class="opt-desc">${esc(i.desc)}</span>`:''}</div>`).join(''):'<div class="searchable-select-empty">No matches</div>'
}
function toggleSearchableSelect(id){const w=document.getElementById(id);const open=w.classList.contains('open');document.querySelectorAll('.searchable-select.open').forEach(e=>{if(e.id!==id)e.classList.remove('open')});if(open)w.classList.remove('open');else{w.classList.add('open');updateSearchableSelectUI(id);const inp=w.querySelector('.searchable-select-search input');if(inp){inp.value='';setTimeout(()=>inp.focus(),50)}}}
function filterSearchableOptions(inp){const w=inp.closest('.searchable-select');if(w)updateSearchableSelectUI(w.id,inp.value)}
function selectSearchableOption(id,val){const ss=searchableSelects[id];if(!ss)return;ss.selectedValue=val;const ti=document.getElementById(ss.targetInputId);if(ti){ti.value=val;ti.dispatchEvent(new Event('change',{bubbles:true}))}document.getElementById(id).classList.remove('open');updateSearchableSelectUI(id);if(ss.onChange)ss.onChange(val)}
document.addEventListener('click',e=>{if(!e.target.closest('.searchable-select'))document.querySelectorAll('.searchable-select.open').forEach(el=>el.classList.remove('open'))});

function toggleSectionBuilder(){document.getElementById('sectionBuilder').style.display=document.getElementById('examHasSections').checked?'block':'none'}
function addRequiredSection(d){requiredSections.push({id:Date.now()+Math.random(),name:d?.name||'',count:d?.count||5});renderSections()}
function addCompulsorySection(d){compulsorySections.push({id:Date.now()+Math.random(),name:d?.name||'',count:d?.count||5});renderSections()}
function addNormalSection(d){normalSections.push({id:Date.now()+Math.random(),name:d?.name||'',count:d?.count||5});renderSections()}
function removeSection(list,id){if(list==='req')requiredSections=requiredSections.filter(s=>s.id!==id);if(list==='comp')compulsorySections=compulsorySections.filter(s=>s.id!==id);if(list==='norm')normalSections=normalSections.filter(s=>s.id!==id);renderSections()}
function updateSectionField(list,id,field,val){const arr=list==='req'?requiredSections:list==='comp'?compulsorySections:normalSections;const s=arr.find(x=>x.id===id);if(s){if(field==='name')s.name=val;if(field==='count')s.count=parseInt(val)||0}}
function renderSections(){const rs=document.getElementById('requiredSectionsList'),cs=document.getElementById('compulsorySectionsList'),ns=document.getElementById('normalSectionsList');rs.innerHTML=requiredSections.length?requiredSections.map(s=>`<div class="section-row"><input type="text" placeholder="Section name" value="${esc(s.name)}" onchange="updateSectionField('req',${s.id},'name',this.value)"><input type="number" placeholder="MCQ" value="${s.count}" onchange="updateSectionField('req',${s.id},'count',this.value)"><button class="btn-remove" onclick="removeSection('req',${s.id})">✕</button></div>`).join(''):'<p style="color:var(--t4);font-size:.75rem;padding:8px">None</p>';cs.innerHTML=compulsorySections.length?compulsorySections.map(s=>`<div class="section-row"><input type="text" placeholder="Section name" value="${esc(s.name)}" onchange="updateSectionField('comp',${s.id},'name',this.value)"><input type="number" placeholder="MCQ" value="${s.count}" onchange="updateSectionField('comp',${s.id},'count',this.value)"><button class="btn-remove" onclick="removeSection('comp',${s.id})">✕</button></div>`).join(''):'<p style="color:var(--t4);font-size:.75rem;padding:8px">None</p>';ns.innerHTML=normalSections.length?normalSections.map(s=>`<div class="section-row"><input type="text" placeholder="Section name" value="${esc(s.name)}" onchange="updateSectionField('norm',${s.id},'name',this.value)"><input type="number" placeholder="MCQ" value="${s.count}" onchange="updateSectionField('norm',${s.id},'count',this.value)"><button class="btn-remove" onclick="removeSection('norm',${s.id})">✕</button></div>`).join(''):'<p style="color:var(--t4);font-size:.75rem;padding:8px">None</p>'}

function clearQuestionsJson(){const t=document.getElementById('questionsJson');if(t)t.value='';const r=document.getElementById('questionUploadResult');if(r)r.innerHTML=''}
document.getElementById('uploadSectionSelect').addEventListener('change',clearQuestionsJson);

function updateUploadSectionSelector(examId){const wrap=document.getElementById('uploadSectionWrap');const sel=document.getElementById('uploadSectionSelect');if(!wrap||!sel)return;const exam=allExams.find(e=>e.id==examId);if(exam?.has_sections&&exam?.section_config){try{const c=JSON.parse(exam.section_config);const all=[...(c.required||[]).map(s=>s.name),...(c.compulsory_group||[]).map(s=>s.name),...(c.normal_group||[]).map(s=>s.name)];sel.innerHTML='<option value="">All Sections</option>'+all.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('');wrap.classList.add('show')}catch(e){wrap.classList.remove('show')}}else{wrap.classList.remove('show')}}

function rebuildSearchableSelects(){registerSearchableSelect('questionExamSelectWrap',allExams.map(e=>({value:e.id,label:e.name,desc:e.batch_name||''})),'questionExamSelect',(val)=>{if(val){clearQuestionsJson();loadQuestionsForExam();updateUploadSectionSelector(val)}});registerSearchableSelect('resourceExamSelectWrap',allExams.map(e=>({value:e.id,label:e.name,desc:e.batch_name||''})),'resourceExamSelect',(val)=>{if(val)loadResourcesForTarget()});registerSearchableSelect('resourceBatchSelectWrap',allBatches.map(b=>({value:b.id,label:b.name,desc:(b.exam_count||0)+' exams'})),'resourceBatchSelect',(val)=>{if(val)loadResourcesForTarget()});registerSearchableSelect('resultFilterExamWrap',[{value:'',label:'All Exams',desc:''},...allExams.map(e=>({value:e.id,label:e.name,desc:e.batch_name||''}))],'resultFilterExam',(val)=>{resultsPageNum=1;loadResults()});registerSearchableSelect('examBatchSelectWrap',[{value:'',label:'No batch',desc:''},...allBatches.map(b=>({value:b.id,label:b.name,desc:(b.exam_count||0)+' exams'}))],'examBatchSelect',()=>{},{placeholder:'Select batch (optional)'});registerSearchableSelect('batchCodesSelectWrap',allBatches.map(b=>({value:b.id,label:b.name,desc:(b.exam_count||0)+' exams'})),'batchCodesSelect',(val)=>{if(val){document.getElementById('batchCodesPanel').style.display='block';document.getElementById('newCodeBanner').innerHTML='';loadBatchCodes()}else{document.getElementById('batchCodesPanel').style.display='none'}});Object.keys(searchableSelects).forEach(k=>updateSearchableSelectUI(k))}

async function loadDashboard(){const user=getUser();if(!user?.is_admin){window.location.href='/';return}const[exams,batches,users,results]=await Promise.all([apiFetch('/exams'),apiFetch('/batches'),apiFetch('/admin/users'),apiFetch('/admin/results')]);
  const failures=[];
  if(!exams.ok)failures.push('/exams -> '+exams.status+' '+(exams.data.error||JSON.stringify(exams.data)));
  if(!batches.ok)failures.push('/batches -> '+batches.status+' '+(batches.data.error||JSON.stringify(batches.data)));
  if(!users.ok)failures.push('/admin/users -> '+users.status+' '+(users.data.error||JSON.stringify(users.data)));
  if(!results.ok)failures.push('/admin/results -> '+results.status+' '+(results.data.error||JSON.stringify(results.data)));
  const banner=document.getElementById('debugErrorBanner');
  if(banner){if(failures.length){banner.style.display='block';banner.innerHTML='<strong>Data failed to load. Details:</strong><br>'+failures.map(f=>esc(f)).join('<br>')}else{banner.style.display='none'}}
  const el=Array.isArray(exams.data?.exams)?exams.data.exams:[],bl=Array.isArray(batches.data)?batches.data:[],ul=Array.isArray(users.data)?users.data:[],rl=Array.isArray(results.data)?results.data:[];document.getElementById('statExams').textContent=el.length;document.getElementById('statBatches').textContent=bl.length;document.getElementById('statUsers').textContent=ul.length;document.getElementById('statSubmissions').textContent=rl.length;document.getElementById('recentTable').innerHTML=`<table><thead><tr><th>Rank</th><th>User</th><th>Exam</th><th>Score</th><th>%</th><th>Date</th></tr></thead><tbody>${rl.slice(0,10).map(r=>`<tr><td>#${r.rank||'—'}</td><td><strong>${esc(r.user_name)}</strong><br><span style="font-size:.65rem;color:var(--t4)">${esc(r.email)}</span></td><td>${esc(r.exam_name)}</td><td>${r.score}/${r.total_questions}</td><td>${(r.percentage||0).toFixed(1)}%</td><td>${formatDate(r.submitted_at)}</td></tr>`).join('')||'<tr><td colspan="6">No submissions</td></tr>'}</tbody></table>`}
async function loadExams(){const{data}=await apiFetch('/exams');allExams=Array.isArray(data?.exams)?data.exams:[];rebuildSearchableSelects();renderExams()}
async function loadBatches(){const{data}=await apiFetch('/batches');allBatches=Array.isArray(data)?data:[];rebuildSearchableSelects();renderBatches()}

function renderExams(){const q=normalizeSearch(document.getElementById('examSearchInput').value||'');let filteredAll=allExams;if(q){filteredAll=allExams.map(e=>({...e,_s:Math.max(fieldMatchScore(q,e.name),fieldMatchScore(q,e.description||''),fieldMatchScore(q,e.batch_name||''))})).filter(e=>e._s>=0).sort((a,b)=>b._s-a._s)}const{items:filtered,page,totalPages,total}=paginateList(filteredAll,examsPageNum,PAGE_SIZE);examsPageNum=page;document.getElementById('examsTable').innerHTML=`<table><thead><tr><th>Name</th><th>Batch</th><th>Type</th><th>Status</th><th>Marks/Q</th><th>Questions</th><th>Leaderboard</th><th>Actions</th></tr></thead><tbody>${filtered.map(e=>{let st='<span class="badge badge-open">Open</span>';if(e.is_closed)st='<span class="badge badge-closed">Closed</span>';else if(e.is_live)st='<span class="badge badge-live">Live</span>';else if(e.scheduled_at&&new Date(e.scheduled_at)>new Date())st='<span class="badge badge-scheduled">Scheduled</span>';return `<tr><td><strong>${esc(e.name)}</strong>${e.has_sections?' <span class="badge badge-sectional">Sectional</span>':''}${e.is_practice_exam?' <span class="badge badge-sectional" style="background:#e0e7ff;color:#4338ca">Practice-only</span>':''}${e.description?`<br><span style="font-size:.65rem;color:var(--t4)">${esc(e.description)}</span>`:''}</td><td>${esc(e.batch_name)||'—'}</td><td><span class="badge ${e.is_premium?'badge-premium':'badge-free'}">${e.is_premium?'Premium':'Free'}</span></td><td>${st}</td><td>${e.marks_per_question||1}</td><td>${e.question_count||0}</td><td>${e.leaderboard_enabled?'<span class="badge badge-open">On</span>':'<span class="badge badge-closed">Off</span>'}</td><td><button class="btn btn-outline btn-sm" onclick="openExamModal(${e.id})">Edit</button><button class="btn btn-outline btn-sm" style="color:${e.is_closed?'var(--green)':'var(--red)'}" onclick="toggleExam(${e.id})">${e.is_closed?'Open':'Close'}</button><button class="btn btn-danger btn-sm" onclick="deleteExam(${e.id})">Delete</button></td></tr>`}).join('')||'<tr><td colspan="8" style="text-align:center;padding:24px;color:var(--t3)">No exams found</td></tr>'}</tbody></table>${pagerHtml(page,totalPages,total,'goToExamsPage')}`}
function goToExamsPage(p){examsPageNum=p;renderExams()}
function renderBatches(){const q=normalizeSearch(document.getElementById('batchSearchInput').value||'');let filteredAll=allBatches;if(q){filteredAll=allBatches.map(b=>({...b,_s:Math.max(fieldMatchScore(q,b.name),fieldMatchScore(q,b.description||''))})).filter(b=>b._s>=0).sort((a,b)=>b._s-a._s)}const{items:filtered,page,totalPages,total}=paginateList(filteredAll,batchesPageNum,PAGE_SIZE);batchesPageNum=page;document.getElementById('batchesTable').innerHTML=`<table><thead><tr><th>Name</th><th>Fee</th><th>Exams</th><th>Visibility</th><th>Actions</th></tr></thead><tbody>${filtered.map(b=>`<tr><td><strong>${esc(b.name)}</strong></td><td>${b.fee?('৳'+b.fee):'Free'}</td><td><span class="badge badge-free">${b.exam_count||0} exams</span></td><td>${b.is_public?'<span class="badge badge-open">Public</span>':'<span class="badge badge-closed">Hidden</span>'}</td><td><button class="btn btn-outline btn-sm" onclick="openBatchUsersModal(${b.id},'${esc(b.name).replace(/'/g,"\\'")}')">Users</button><button class="btn btn-outline btn-sm" onclick="openBatchModal(${b.id})">Edit</button><button class="btn btn-danger btn-sm" onclick="deleteBatch(${b.id})">Delete</button></td></tr>`).join('')||'<tr><td colspan="5" style="text-align:center;padding:24px;color:var(--t3)">No batches found</td></tr>'}</tbody></table>${pagerHtml(page,totalPages,total,'goToBatchesPage')}`}
function goToBatchesPage(p){batchesPageNum=p;renderBatches()}
function onExamSearchInput(){examsPageNum=1;renderExams()}
function onBatchSearchInput(){batchesPageNum=1;renderBatches()}

function openExamModal(id=null){editingExamId=id;const e=id?allExams.find(x=>x.id==id):null;document.getElementById('examModalTitle').textContent=e?'Edit Exam':'New Exam';document.getElementById('examName').value=e?.name||'';document.getElementById('examDesc').value=e?.description||'';document.getElementById('examTime').value=e?.time_limit||30;document.getElementById('examNeg').value=e?.negative_marking||0;document.getElementById('examMarksPerQ').value=e?.marks_per_question||1;document.getElementById('examLive').value=e?.live_deadline_hours||0;if(e?.scheduled_at){const d=new Date(e.scheduled_at);const local=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);document.getElementById('examScheduledAt').value=local}else{document.getElementById('examScheduledAt').value=''}document.getElementById('examPremium').checked=e?.is_premium||false;document.getElementById('examPractice').checked=id?!!e?.allow_practice:true;document.getElementById('examLeaderboard').checked=id?!!e?.leaderboard_enabled:true;document.getElementById('examPracticeOnly').checked=e?.is_practice_exam===1;document.getElementById('examHasSections').checked=e?.has_sections===1;document.getElementById('examBatchSelect').value=e?.batch_id||'';if(searchableSelects['examBatchSelectWrap']){searchableSelects['examBatchSelectWrap'].selectedValue=e?.batch_id||'';updateSearchableSelectUI('examBatchSelectWrap')}requiredSections=[];compulsorySections=[];normalSections=[];if(e?.has_sections&&e?.section_config){try{const c=JSON.parse(e.section_config);(c.required||[]).forEach(s=>requiredSections.push({id:Date.now()+Math.random(),name:s.name,count:s.count}));(c.compulsory_group||[]).forEach(s=>compulsorySections.push({id:Date.now()+Math.random(),name:s.name,count:s.count}));(c.normal_group||[]).forEach(s=>normalSections.push({id:Date.now()+Math.random(),name:s.name,count:s.count}));document.getElementById('maxOptional').value=c.max_optional||2;document.getElementById('minCompulsory').value=c.min_from_compulsory||1}catch(e){}}toggleSectionBuilder();renderSections();document.getElementById('examModal').classList.add('open')}
async function saveExam(){const hasSections=document.getElementById('examHasSections').checked;let config='';if(hasSections){config=JSON.stringify({required:requiredSections.filter(s=>s.name.trim()).map(s=>({name:s.name.trim(),count:s.count})),compulsory_group:compulsorySections.filter(s=>s.name.trim()).map(s=>({name:s.name.trim(),count:s.count})),normal_group:normalSections.filter(s=>s.name.trim()).map(s=>({name:s.name.trim(),count:s.count})),max_optional:parseInt(document.getElementById('maxOptional').value)||2,min_from_compulsory:parseInt(document.getElementById('minCompulsory').value)||1})}const sv=document.getElementById('examScheduledAt').value;const body={name:document.getElementById('examName').value.trim(),description:document.getElementById('examDesc').value,time_limit:parseInt(document.getElementById('examTime').value)||30,negative_marking:parseFloat(document.getElementById('examNeg').value)||0,marks_per_question:parseFloat(document.getElementById('examMarksPerQ').value)||1,is_premium:document.getElementById('examPremium').checked?1:0,allow_practice:document.getElementById('examPractice').checked?1:0,leaderboard_enabled:document.getElementById('examLeaderboard').checked?1:0,is_practice_exam:document.getElementById('examPracticeOnly').checked?1:0,batch_id:document.getElementById('examBatchSelect').value||null,live_deadline_hours:parseInt(document.getElementById('examLive').value)||0,scheduled_at:sv?new Date(sv).toISOString():null,has_sections:hasSections?1:0,section_config:config};const url=editingExamId?`/admin/exams/${editingExamId}`:'/admin/exams';const method=editingExamId?'PUT':'POST';const{ok,data}=await apiFetch(url,{method,body:JSON.stringify(body)});if(ok){closeModal('examModal');toast('Exam saved');await loadExams();await loadDashboard()}else alert(data.error||'Failed to save exam')}
async function deleteExam(id){if(confirm('Delete this exam?')){await apiFetch(`/admin/exams/${id}`,{method:'DELETE'});toast('Exam deleted');await loadExams();await loadDashboard()}}
async function toggleExam(id){const e=allExams.find(x=>x.id==id);if(!e)return;await apiFetch(`/admin/exams/${id}/toggle`,{method:'POST',body:JSON.stringify({is_closed:e.is_closed?0:1})});toast('Exam '+(e.is_closed?'opened':'closed'));await loadExams()}

