function currentBatchCodesId(){return document.getElementById('batchCodesSelect').value||null}
async function loadBatchCodes(){const id=currentBatchCodesId();if(!id)return;const{data}=await apiFetch(`/admin/batches/${id}/codes`);renderBatchCodes(data||[])}
function renderBatchCodes(codes){document.getElementById('batchCodesTable').innerHTML=`<table><thead><tr><th>Code</th><th>Status</th><th>Used By</th><th>Created</th><th>Used</th><th></th></tr></thead><tbody>${codes.map(c=>`<tr><td style="font-family:monospace">${esc(c.code)}</td><td>${c.status==='used'?'<span class="badge badge-closed">Used</span>':'<span class="badge badge-open">Active</span>'}</td><td>${c.used_by_name?`${esc(c.used_by_name)}<br><span style="font-size:.65rem;color:var(--t4)">${esc(c.used_by_email)}</span>`:'—'}</td><td>${formatDate(c.created_at)}</td><td>${c.used_at?formatDate(c.used_at):'—'}</td><td><button class="btn btn-danger btn-sm" onclick="deleteBatchCode(${c.id})">Delete</button></td></tr>`).join('')||'<tr><td colspan="6" style="text-align:center;padding:24px;color:var(--t3)">No codes generated yet</td></tr>'}</tbody></table>`}
async function generateBatchCode(){const id=currentBatchCodesId();if(!id)return;const{ok,data}=await apiFetch(`/admin/batches/${id}/codes`,{method:'POST'});if(ok){document.getElementById('newCodeBanner').innerHTML=`<div class="alert alert-success" style="font-family:monospace;font-size:1rem;font-weight:600;display:flex;align-items:center;justify-content:space-between;gap:12px">${esc(data.code)}<button class="btn btn-outline btn-sm" onclick="copyText('${data.code}')">Copy</button></div>`;toast('Code generated');await loadBatchCodes()}else alert(data.error||'Failed to generate code')}
function copyText(t){navigator.clipboard?.writeText(t).then(()=>toast('Copied')).catch(()=>{})}
async function deleteBatchCode(codeId){if(!confirm('Delete this code?\n\nIf it has already been used, the student keeps their access — this only removes the code record.'))return;const{ok,data}=await apiFetch(`/admin/batch-codes/${codeId}`,{method:'DELETE'});if(ok){toast('Code deleted');await loadBatchCodes()}else alert(data.error||'Failed to delete code')}
async function clearUsedBatchCodes(){const id=currentBatchCodesId();if(!id)return;if(!confirm('Clear all used codes for this batch?\n\nThis only deletes the code history to save space — everyone who already redeemed a code keeps their access. This cannot be undone.'))return;const{ok,data}=await apiFetch(`/admin/batches/${id}/codes-used`,{method:'DELETE'});if(ok){toast('Used codes cleared');await loadBatchCodes()}else alert(data.error||'Failed to clear codes')}

function openBatchModal(id=null){editingBatchId=id;const b=id?allBatches.find(x=>x.id==id):null;document.getElementById('batchModalTitle').textContent=id?'Edit Batch':'New Batch';document.getElementById('batchName').value=b?.name||'';document.getElementById('batchDesc').value=b?.description||'';document.getElementById('batchImageUrl').value=b?.image_url||'';document.getElementById('batchFee').value=b?.fee||'';document.getElementById('batchIsPublic').checked=b?.is_public===1;const slugWrap=document.getElementById('batchSlugWrap');if(b?.public_slug){slugWrap.style.display='block';document.getElementById('batchSlugDisplay').value=window.location.origin+'/payment.html?batch='+b.public_slug}else{slugWrap.style.display='none'}document.getElementById('batchModal').classList.add('open')}
let currentBatchUsersId=null,currentBatchUsersName='';
function daysRemainingLabel(d){if(d===null||d===undefined)return'Permanent';if(d<=0)return'Expires today';return d+' day'+(d===1?'':'s')+' left'}
function batchUserRow(u,removeFn,tagCls,tagLabel){return `<div class="batch-user-row"><div class="batch-user-info"><div class="batch-user-name">${esc(u.name)} <span class="premium-tag ${tagCls}" style="margin-left:4px">${tagLabel}</span></div><div class="batch-user-email">${esc(u.email)}</div><div class="batch-user-days">${daysRemainingLabel(u.days_remaining)}</div></div><button class="btn btn-danger btn-xs" onclick="${removeFn}">Remove</button></div>`}
async function openBatchUsersModal(id,name){currentBatchUsersId=id;currentBatchUsersName=name;document.getElementById('batchUsersTitle').textContent='Users — '+name;document.getElementById('batchUsersBody').innerHTML='<div class="skeleton" style="height:40px"></div>';document.getElementById('batchUsersModal').classList.add('open');await loadBatchUsers()}
async function loadBatchUsers(){const{ok,data}=await apiFetch(`/admin/batches/${currentBatchUsersId}/users`);if(!ok){document.getElementById('batchUsersBody').innerHTML='<p style="color:var(--t3);text-align:center;padding:16px">Failed to load.</p>';return}const bu=data.batch_users||[],au=data.account_users||[];let html='';html+=`<div class="batch-users-group-label">Batch Premium (${bu.length})</div>`;html+=bu.length?bu.map(u=>batchUserRow(u,`removeBatchUser(${u.user_id})`,'pt-batch','Batch')).join(''):'<p style="color:var(--t4);font-size:.75rem;padding:6px 0">No one has been granted premium for this batch specifically.</p>';html+=`<div class="batch-users-group-label">Account-wide Premium (${au.length})</div>`;html+=au.length?au.map(u=>batchUserRow(u,`removeAccountUser(${u.user_id})`,'pt-account','Account')).join(''):'<p style="color:var(--t4);font-size:.75rem;padding:6px 0">No account-wide premium users.</p>';document.getElementById('batchUsersBody').innerHTML=html}
async function removeBatchUser(uid){if(!confirm('Remove this user\'s access to this batch?'))return;await apiFetch('/admin/revoke-premium',{method:'DELETE',body:JSON.stringify({user_id:uid,batch_id:currentBatchUsersId})});toast('Removed from batch');await loadBatchUsers();await loadUsers()}
async function removeAccountUser(uid){if(!confirm('This user has account-wide premium, which gives them access to every batch and exam — not just this one. Revoke it entirely?'))return;await apiFetch('/admin/revoke-account-premium',{method:'DELETE',body:JSON.stringify({user_id:uid})});toast('Account premium revoked');await loadBatchUsers();await loadUsers()}
async function saveBatch(){const body={name:document.getElementById('batchName').value.trim(),description:document.getElementById('batchDesc').value,image_url:document.getElementById('batchImageUrl').value.trim(),fee:parseFloat(document.getElementById('batchFee').value)||0,is_public:document.getElementById('batchIsPublic').checked?1:0};const url=editingBatchId?`/admin/batches/${editingBatchId}`:'/admin/batches';const method=editingBatchId?'PUT':'POST';const{ok,data}=await apiFetch(url,{method,body:JSON.stringify(body)});if(ok){await loadBatches();await loadExams();await loadDashboard();if(!editingBatchId&&data?.public_slug){editingBatchId=data.id;document.getElementById('batchModalTitle').textContent='Edit Batch';document.getElementById('batchSlugWrap').style.display='block';document.getElementById('batchSlugDisplay').value=window.location.origin+'/payment.html?batch='+data.public_slug;toast('Batch created — copy its payment link below')}else{closeModal('batchModal');toast('Batch saved')}}}
async function deleteBatch(id){if(confirm('Delete this batch?')){await apiFetch(`/admin/batches/${id}`,{method:'DELETE'});toast('Batch deleted');await loadBatches();await loadExams();await loadDashboard()}}

async function loadQuestionsForExam(){const id=document.getElementById('questionExamSelect').value;if(!id){document.getElementById('questionsList').innerHTML='<p style="color:var(--t3);padding:16px">Select an exam</p>';return}const{data}=await apiFetch(`/admin/questions/${id}`);const qs=data||[];document.getElementById('questionsList').innerHTML=qs.length?qs.map((q,i)=>`<div style="padding:10px;border-bottom:1px solid var(--border)"><strong>${i+1}.</strong> ${q.section?`<span style="background:#e8f0fe;color:var(--blue);font-size:.65rem;padding:2px 8px;border-radius:20px;margin-right:6px">${esc(q.section)}</span>`:''}${esc(q.question_text||'')} <span style="color:var(--green)">(${q.correct_answer})</span></div>`).join(''):'<p style="color:var(--t3);padding:20px;text-align:center">No questions yet</p>'}
async function uploadQuestions(){const examId=document.getElementById('questionExamSelect').value;const json=document.getElementById('questionsJson').value;const section=document.getElementById('uploadSectionSelect').value;if(!examId||!json){alert('Select exam and paste JSON');return}try{const questions=JSON.parse(json);if(document.getElementById('replaceQuestions').checked)await apiFetch(`/admin/questions/${examId}`,{method:'DELETE'});const{data}=await apiFetch('/admin/questions/bulk',{method:'POST',body:JSON.stringify({exam_id:parseInt(examId),questions,section})});document.getElementById('questionUploadResult').innerHTML=`<div class="alert alert-success">${data.inserted} questions uploaded</div>`;setTimeout(()=>document.getElementById('questionUploadResult').innerHTML='',3000);clearQuestionsJson();await loadQuestionsForExam();await loadExams();await loadDashboard()}catch(e){alert('Invalid JSON format')}}
async function deleteAllQuestions(){const id=document.getElementById('questionExamSelect').value;if(id&&confirm('Delete ALL questions?')){await apiFetch(`/admin/questions/${id}`,{method:'DELETE'});await loadQuestionsForExam();await loadExams();await loadDashboard()}}

function setResourceType(t){currentResourceType=t;document.querySelectorAll('.resource-type-btn').forEach(b=>b.classList.toggle('active',b.dataset.type===t));document.getElementById('resourceExamGroup').style.display=t==='exam'?'block':'none';document.getElementById('resourceBatchGroup').style.display=t==='batch'?'block':'none';loadResourcesForTarget()}
async function loadResourcesForTarget(){const id=currentResourceType==='exam'?document.getElementById('resourceExamSelect').value:document.getElementById('resourceBatchSelect').value;if(!id){document.getElementById('resourcesList').innerHTML='<div class="resource-empty">Select an exam or batch</div>';return}currentResourceTargetId=parseInt(id);const ep=currentResourceType==='exam'?`/admin/exams/${id}/resources`:`/admin/batches/${id}/resources`;const{data}=await apiFetch(ep);const rs=data||[];document.getElementById('resourcesList').innerHTML=rs.length?`<div class="resource-list">${rs.map(r=>`<div class="resource-item"><div class="resource-info"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg><div><div class="resource-title">${esc(r.title)}</div><div class="resource-link">${isImageURL(r.link)?`<img src="${esc(r.link)}" class="resource-link-img" alt="">`:esc(r.link)}</div></div></div><div class="resource-actions"><button class="btn btn-danger btn-sm" onclick="deleteResource(${r.id})">Delete</button></div></div>`).join('')}</div>`:'<div class="resource-empty">No resources added yet</div>'}
async function addResource(){const t=document.getElementById('newResourceTitle').value.trim();const l=document.getElementById('newResourceLink').value.trim();if(!currentResourceTargetId||!t||!l){alert('Select target and fill all fields');return}const ep=currentResourceType==='exam'?'/admin/resources':'/admin/batch-resources';const body=currentResourceType==='exam'?{exam_id:currentResourceTargetId,title:t,link:l}:{batch_id:currentResourceTargetId,title:t,link:l};const{ok}=await apiFetch(ep,{method:'POST',body:JSON.stringify(body)});if(ok){document.getElementById('newResourceTitle').value='';document.getElementById('newResourceLink').value='';toast('Resource added');await loadResourcesForTarget()}}
