let userFilterType='all';
function userRowHtml(u){let prem='';if(u.premium_grants&&u.premium_grants.length){prem=u.premium_grants.map(g=>{const c=g.grant_scope==='exam'?'pt-exam':g.grant_scope==='batch'?'pt-batch':'pt-account';const n=g.exam_name||g.batch_name||(g.grant_scope==='account'?'Account':g.grant_scope);const rf=g.grant_scope==='exam'?`revokeExamPremium(${u.id},${g.exam_id})`:g.grant_scope==='batch'?`revokeBatchPremium(${u.id},${g.batch_id})`:`revokeAccountPremium(${u.id})`;return `<span class="premium-tag ${c}">${esc(n)}<button class="revoke-btn" onclick="${rf}">✕</button></span>`}).join('')}else prem='<span style="color:var(--t4);font-size:.7rem">None</span>';let st='<span class="badge badge-free">Active</span>';if(u.is_banned)st='<span class="badge badge-banned">Banned</span>';else if(u.is_admin)st='<span class="badge badge-admin">Admin</span>';let act='';if(!u.is_admin){act=`<button class="btn btn-primary btn-xs" onclick="openGrantModal(${u.id},'${esc(u.name)}')">Grant</button>`;if(u.is_banned)act+=` <button class="btn btn-outline btn-xs" onclick="unbanUser(${u.id})">Unban</button>`;else act+=` <button class="btn btn-outline btn-xs" style="color:#e37400;border-color:#e37400" onclick="confirmBan(${u.id},'${esc(u.name)}')">Ban</button>`;act+=` <button class="btn btn-danger btn-xs" onclick="confirmDeleteUser(${u.id},'${esc(u.name)}')">Delete</button>`}return `<tr><td><strong>${esc(u.name)}</strong></td><td style="color:var(--t4);font-size:.75rem">${esc(u.email)}</td><td>${u.is_admin?'Admin':'Student'}</td><td>${st}</td><td style="max-width:180px">${prem}</td><td>${act||'—'}</td></tr>`}
function isActiveGrant(g){return!g.expires_at||new Date(g.expires_at).getTime()>Date.now()}
function userMatchesPremiumFilter(u){
  if(userFilterType==='all')return true;
  const grants=u.premium_grants||[];
  const now=Date.now();
  if(userFilterType==='batch'){
    const bg=grants.filter(g=>g.grant_scope==='batch'&&isActiveGrant(g));
    if(!bg.length)return false;
    const bid=document.getElementById('userFilterBatchId').value;
    return bid?bg.some(g=>String(g.batch_id)===String(bid)):true;
  }
  if(userFilterType==='exam'){
    const eg=grants.filter(g=>g.grant_scope==='exam'&&isActiveGrant(g));
    if(!eg.length)return false;
    const eid=document.getElementById('userFilterExamId').value;
    return eid?eg.some(g=>String(g.exam_id)===String(eid)):true;
  }
  if(userFilterType==='account')return!!(u.premium_until&&new Date(u.premium_until).getTime()>now);
  if(userFilterType==='none'){
    const hasBatch=grants.some(g=>g.grant_scope==='batch'&&isActiveGrant(g));
    const hasExam=grants.some(g=>g.grant_scope==='exam'&&isActiveGrant(g));
    const hasAccount=!!(u.premium_until&&new Date(u.premium_until).getTime()>now);
    return!hasBatch&&!hasExam&&!hasAccount;
  }
  return true;
}
function onUserFilterTypeChange(){
  userFilterType=document.getElementById('userFilterType').value;
  usersPageNum=1;
  document.getElementById('userFilterBatchWrap').style.display=userFilterType==='batch'?'block':'none';
  document.getElementById('userFilterExamWrap').style.display=userFilterType==='exam'?'block':'none';
  if(userFilterType==='batch'){document.getElementById('userFilterBatchId').value='';registerSearchableSelect('userFilterBatchWrap',[{value:'',label:'Any batch',desc:''}].concat(allBatches.map(b=>({value:b.id,label:b.name,desc:(b.exam_count||0)+' exams'}))),'userFilterBatchId',()=>renderUsersTable(),{defaultValue:'',placeholder:'Any batch'});updateSearchableSelectUI('userFilterBatchWrap')}
  if(userFilterType==='exam'){document.getElementById('userFilterExamId').value='';registerSearchableSelect('userFilterExamWrap',[{value:'',label:'Any exam',desc:''}].concat(allExams.map(e=>({value:e.id,label:e.name,desc:e.batch_name||''}))),'userFilterExamId',()=>renderUsersTable(),{defaultValue:'',placeholder:'Any exam'});updateSearchableSelectUI('userFilterExamWrap')}
  renderUsersTable();
}
function renderUsersTable(){const filteredAll=allUsers.filter(userMatchesPremiumFilter);const{items:filtered,page,totalPages,total}=paginateList(filteredAll,usersPageNum,PAGE_SIZE);usersPageNum=page;document.getElementById('usersTable').innerHTML=`<table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Premium</th><th>Actions</th></tr></thead><tbody>${filtered.map(userRowHtml).join('')||'<tr><td colspan="6" style="text-align:center;padding:24px;color:var(--t3)">No users match this filter</td></tr>'}</tbody></table>${pagerHtml(page,totalPages,total,'goToUsersPage')}`;const activeQuery=document.getElementById('userSearchInput')?.value;if(activeQuery)onUserSearchInput()}
function goToUsersPage(p){usersPageNum=p;renderUsersTable()}
async function loadUsers(){const{data}=await apiFetch('/admin/users');allUsers=Array.isArray(data)?data:[];renderUsersTable()}

function openGrantModal(id,name){grantUserId=id;document.getElementById('grantUserDisplay').textContent=name;registerSearchableSelect('grantExamSelectWrap',allExams.map(e=>({value:e.id,label:e.name,desc:e.batch_name||''})),'grantExam',()=>{},{defaultValue:'',placeholder:'Search exams...'});registerSearchableSelect('grantBatchSelectWrap',allBatches.map(b=>({value:b.id,label:b.name,desc:(b.exam_count||0)+' exams'})),'grantBatch',()=>{},{defaultValue:'',placeholder:'Search batches...'});updateSearchableSelectUI('grantExamSelectWrap');updateSearchableSelectUI('grantBatchSelectWrap');toggleGrantScope();document.getElementById('grantModal').classList.add('open')}
function toggleGrantScope(){const s=document.getElementById('grantScope').value;document.getElementById('grantExamGroup').style.display=s==='exam'?'block':'none';document.getElementById('grantBatchGroup').style.display=s==='batch'?'block':'none'}
async function submitGrant(){const s=document.getElementById('grantScope').value;const d=document.getElementById('grantDuration').value;const body={user_id:grantUserId,grant_scope:s,duration_hours:d?parseInt(d):null};if(s==='exam')body.exam_id=parseInt(document.getElementById('grantExam').value);if(s==='batch')body.batch_id=parseInt(document.getElementById('grantBatch').value);const{ok}=await apiFetch('/admin/grant-premium',{method:'POST',body:JSON.stringify(body)});if(ok){closeModal('grantModal');toast('Premium granted');await loadUsers()}}
async function revokeExamPremium(uid,eid){if(!confirm('Revoke exam premium?'))return;await apiFetch('/admin/revoke-premium',{method:'DELETE',body:JSON.stringify({user_id:uid,exam_id:eid})});toast('Premium revoked');await loadUsers()}
async function revokeBatchPremium(uid,bid){if(!confirm('Revoke batch premium?'))return;await apiFetch('/admin/revoke-premium',{method:'DELETE',body:JSON.stringify({user_id:uid,batch_id:bid})});toast('Premium revoked');await loadUsers()}
async function revokeAccountPremium(uid){if(!confirm('Revoke account premium?'))return;await apiFetch('/admin/revoke-account-premium',{method:'DELETE',body:JSON.stringify({user_id:uid})});toast('Premium revoked');await loadUsers()}

function confirmBan(uid,name){document.getElementById('confirmActionTitle').textContent='Ban User';document.getElementById('confirmActionBody').innerHTML=`<p>Are you sure you want to <strong style="color:#e37400">ban</strong> <strong>${esc(name)}</strong>?</p><p style="font-size:.8rem;color:var(--t3)">They will be unable to login. Data preserved.</p>`;document.getElementById('confirmActionFooter').innerHTML=`<button class="btn btn-outline" onclick="closeModal('confirmActionModal')">Cancel</button><button class="btn btn-primary" style="background:#e37400" onclick="banUser(${uid})">Ban User</button>`;document.getElementById('confirmActionModal').classList.add('open')}
function confirmDeleteUser(uid,name){document.getElementById('confirmActionTitle').textContent='Delete User Permanently';document.getElementById('confirmActionBody').innerHTML=`<p style="color:var(--red);font-weight:500">This action CANNOT be undone.</p><p>This will permanently delete <strong>${esc(name)}</strong> and all related accounts.</p>`;document.getElementById('confirmActionFooter').innerHTML=`<button class="btn btn-outline" onclick="closeModal('confirmActionModal')">Cancel</button><button class="btn btn-danger" onclick="deleteUser(${uid})">Delete Permanently</button>`;document.getElementById('confirmActionModal').classList.add('open')}
async function banUser(id){const{ok}=await apiFetch(`/admin/users/${id}/ban`,{method:'POST'});if(ok){closeModal('confirmActionModal');toast('User banned');await loadUsers()}}
async function unbanUser(id){const{ok}=await apiFetch(`/admin/users/${id}/unban`,{method:'POST'});if(ok){toast('User unbanned');await loadUsers()}}
async function deleteUser(id){const{ok}=await apiFetch(`/admin/users/${id}/delete`,{method:'DELETE'});if(ok){closeModal('confirmActionModal');toast('User deleted');await loadUsers();await loadDashboard()}}

function onUserSearchInput(){const val=document.getElementById('userSearchInput').value;const btn=document.getElementById('userSearchClear');const box=document.getElementById('userSearchResults');btn.style.display=val?'flex':'none';if(!normalizeSearch(val)){box.classList.remove('show');box.innerHTML='';return}const matches=fuzzyUserSearch(val);if(!matches.length){box.innerHTML='<div class="user-search-empty">No matching users found</div>';box.classList.add('show');return}box.innerHTML=matches.map(u=>{let st='';if(u.is_banned)st='<span class="badge badge-banned">Banned</span>';else if(u.is_admin)st='<span class="badge badge-admin">Admin</span>';let actions=`<button class="btn btn-primary btn-xs" onclick="event.stopPropagation();openGrantModal(${u.id},'${esc(u.name)}')">Grant</button>`;if(!u.is_admin){if(u.is_banned)actions+=` <button class="btn btn-outline btn-xs" onclick="event.stopPropagation();unbanUser(${u.id})">Unban</button>`;else actions+=` <button class="btn btn-outline btn-xs" style="color:#e37400" onclick="event.stopPropagation();confirmBan(${u.id},'${esc(u.name)}')">Ban</button>`;actions+=` <button class="btn btn-danger btn-xs" onclick="event.stopPropagation();confirmDeleteUser(${u.id},'${esc(u.name)}')">Delete</button>`}return `<div class="user-search-item"><div class="user-search-main" onclick="openGrantModal(${u.id},'${esc(u.name)}')"><div class="user-search-name">${esc(u.name)} ${st}</div><div class="user-search-email">${esc(u.email)}</div></div><div class="user-search-actions">${actions}</div></div>`}).join('');box.classList.add('show')}
function clearUserSearch(){document.getElementById('userSearchInput').value='';document.getElementById('userSearchClear').style.display='none';document.getElementById('userSearchResults').classList.remove('show');document.getElementById('userSearchResults').innerHTML=''}

async function loadResults(){const id=document.getElementById('resultFilterExam').value;const url=id?`/admin/results/${id}`:'/admin/results';const{data}=await apiFetch(url);const rsAll=Array.isArray(data)?data:[];let toolbar='';if(id){const exam=allExams.find(e=>e.id==id);toolbar=`<button class="btn btn-primary btn-sm" onclick="downloadResults(${id})">Download TXT</button> <button class="btn btn-danger btn-sm" onclick="deleteExamResults(${id},'${esc(exam?exam.name:'').replace(/'/g,"\\'")}')">Delete All Results (This Exam)</button>`}else if(rsAll.length){toolbar=`<button class="btn btn-danger btn-sm" onclick="deleteAllResultsEverywhere()">Delete ALL Results (Every Exam)</button>`}const{items:rs,page,totalPages,total}=paginateList(rsAll,resultsPageNum,PAGE_SIZE);resultsPageNum=page;document.getElementById('resultsTable').innerHTML=`<div style="margin-bottom:8px">${toolbar}</div><table><thead><tr><th>Rank</th><th>User</th><th>Exam</th><th>Score</th><th>%</th><th>Time</th><th>Date</th><th></th></tr></thead><tbody>${rs.map(r=>`<tr><td><strong>#${r.rank||'—'}</strong></td><td><strong>${esc(r.user_name)}</strong><br><span style="font-size:.65rem;color:var(--t4)">${esc(r.user_email)}</span></td><td>${esc(r.exam_name)}</td><td>${r.score}/${r.total_questions}</td><td><span style="color:${(r.percentage||0)>=80?'var(--green)':(r.percentage||0)>=50?'#e37400':'var(--red)'}">${(r.percentage||0).toFixed(1)}%</span></td><td>${formatTimeTaken(r.time_taken_seconds)}</td><td>${formatDate(r.submitted_at)}</td><td><button class="btn btn-danger btn-sm" onclick="deleteResult(${r.id},'${esc(r.user_name).replace(/'/g,"\\'")}','${esc(r.exam_name).replace(/'/g,"\\'")}')">Delete</button></td></tr>`).join('')||'<tr><td colspan="8">No results</td></tr>'}</tbody></table>${pagerHtml(page,totalPages,total,'goToResultsPage')}`}
function goToResultsPage(p){resultsPageNum=p;loadResults()}
function downloadResults(id){const t=getToken();fetch(API+'/admin/results/'+id+'/download',{headers:{'Authorization':'Bearer '+t}}).then(r=>r.blob()).then(b=>{const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='results.txt';a.click()})}
async function deleteResult(resultId,userName,examName){if(!confirm(`Delete ${userName}'s result for "${examName}"?\n\nThis permanently removes this result from the backend. This cannot be undone.`))return;const{ok,data}=await apiFetch(`/admin/results/${resultId}`,{method:'DELETE'});if(ok){toast('Result deleted');await loadResults();await loadDashboard()}else alert(data.error||'Failed to delete result')}
async function deleteExamResults(examId,examName){if(!confirm(`Delete ALL results for "${examName||'this exam'}"?\n\nEvery user's result for this exam will be permanently removed from the backend and the leaderboard will be cleared. This cannot be undone.`))return;const{ok,data}=await apiFetch(`/admin/exams/${examId}/results`,{method:'DELETE'});if(ok){toast('All results for this exam deleted');await loadResults();await loadDashboard()}else alert(data.error||'Failed to delete results')}
async function deleteAllResultsEverywhere(){if(!confirm('Delete ALL results for EVERY exam on the platform?\n\nThis permanently removes every stored result and leaderboard entry across all exams from the backend. This cannot be undone.'))return;if(!confirm('Are you absolutely sure? This affects every exam and cannot be reversed.'))return;const{ok,data}=await apiFetch('/admin/results',{method:'DELETE'});if(ok){toast('All results deleted');await loadResults();await loadDashboard()}else alert(data.error||'Failed to delete results')}

function toggleNotifTarget(){const s=document.getElementById('notifTarget').value;document.getElementById('notifBatchGroup').style.display=s==='batch'?'block':'none';if(s==='batch'){registerSearchableSelect('notifBatchSelectWrap',allBatches.map(b=>({value:b.id,label:b.name,desc:(b.exam_count||0)+' exams'})),'notifBatchId',()=>{},{defaultValue:'',placeholder:'Search batches...'});updateSearchableSelectUI('notifBatchSelectWrap')}}
async function sendNotification(){const title=document.getElementById('notifTitle').value.trim();if(!title){alert('Title required');return}const targetType=document.getElementById('notifTarget').value;const targetBatchId=document.getElementById('notifBatchId').value;if(targetType==='batch'&&!targetBatchId){alert('Select a batch to notify');return}const body={title,body:document.getElementById('notifBody').value,image_url:document.getElementById('notifImage').value||null,link_url:document.getElementById('notifLink').value||null,target_type:targetType,target_batch_id:targetType==='batch'?parseInt(targetBatchId):null};const{ok}=await apiFetch('/admin/notifications',{method:'POST',body:JSON.stringify(body)});if(ok){document.getElementById('notifResult').innerHTML='<div class="alert alert-success">Notification sent!</div>';document.getElementById('notifTitle').value='';document.getElementById('notifBody').value='';document.getElementById('notifImage').value='';document.getElementById('notifLink').value='';document.getElementById('notifTarget').value='all';document.getElementById('notifBatchId').value='';toggleNotifTarget();toast('Notification sent');await loadNotificationsList();setTimeout(()=>document.getElementById('notifResult').innerHTML='',3000)}}
async function loadNotificationsList(){const{data}=await apiFetch('/admin/notifications');const nsAll=data||[];const{items:ns,page,totalPages,total}=paginateList(nsAll,notifPageNum,8);notifPageNum=page;document.getElementById('notifList').innerHTML=(ns.length?ns.map(n=>{const targetBadge=n.target_type==='batch'?`<span class="badge badge-sectional" style="background:#e0e7ff;color:#4338ca">Batch: ${esc(n.target_batch_name||'Unknown')}</span>`:'<span class="badge badge-free">Everyone</span>';return `<div class="notif-card"><div class="notif-header"><div class="notif-title">${esc(n.title)}</div><button class="btn btn-danger btn-sm" onclick="deleteNotification(${n.id})">Delete</button></div><div class="notif-meta">${targetBadge}<span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>${formatDate(n.created_at)}</span><span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>${n.read_count||0}/${n.total_users||0} read</span><span style="color:var(--t4);font-size:.65rem">by ${esc(n.creator_name||'')}</span></div>${n.body?`<div class="notif-body">${esc(n.body)}</div>`:''}${n.image_url?`<img src="${esc(n.image_url)}" class="notif-img" onerror="this.style.display='none'">`:''}${n.link_url?`<a href="${esc(n.link_url)}" target="_blank" class="notif-link">Open Link</a>`:''}</div>`}).join(''):'<p style="color:var(--t3);text-align:center;padding:16px">No notifications sent</p>')+pagerHtml(page,totalPages,total,'goToNotifPage')}
function goToNotifPage(p){notifPageNum=p;loadNotificationsList()}
async function deleteNotification(id){if(confirm('Delete this notification?')){await apiFetch(`/admin/notifications/${id}`,{method:'DELETE'});toast('Notification deleted');await loadNotificationsList()}}

function toggleMobileNav(){document.getElementById('mobileNavDropdown').classList.toggle('show')}
document.addEventListener('click',e=>{const dd=document.getElementById('mobileNavDropdown');const hb=document.getElementById('hamburger');if(dd&&!dd.contains(e.target)&&!hb.contains(e.target))dd.classList.remove('show')})
function switchSection(s){document.querySelectorAll('.section').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.sidebar-item').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.mobile-nav-dropdown .sidebar-item').forEach(x=>x.classList.remove('active'));document.getElementById('sec-'+s).classList.add('active');document.querySelector(`.sidebar-item[onclick="switchSection('${s}')"]`)?.classList.add('active');document.querySelector(`.mobile-nav-dropdown .sidebar-item[onclick="switchSection('${s}')"]`)?.classList.add('active');if(s==='dashboard')loadDashboard();if(s==='exams')loadExams();if(s==='batches')loadBatches();if(s==='questions'){loadQuestionsForExam()}if(s==='resources'){rebuildSearchableSelects()}if(s==='users')loadUsers();if(s==='results'){rebuildSearchableSelects();loadResults()}if(s==='notifications')loadNotificationsList();document.getElementById('mobileNavDropdown').classList.remove('show')}
function openModal(id){document.getElementById(id).classList.add('open')}
function closeModal(id){document.getElementById(id).classList.remove('open')}
document.querySelectorAll('.modal-overlay').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)m.classList.remove('open')}))
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.modal-overlay.open').forEach(m=>m.classList.remove('open'))})

loadDashboard();loadExams();loadBatches();loadUsers();loadNotificationsList();
